<?php
require_once __DIR__.'/../lib/bootstrap.php';
require_role('admin');
$uid=(int)current_user()['id'];$errors=[];$editId=get_int('edit');
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=post_string('action');$id=(int)($_POST['id']??0);
 if($action==='save'){
  $title=post_string('title',150);$grade=post_string('grade_level',30);$field=post_string('field_name',150);$code=post_string('code',50);$description=post_string('description',2000);
  if($title==='')$errors[]='عنوان درس الزامی است.';
  else{if($id){$s=db()->prepare('UPDATE subjects SET title=?,grade_level=?,field_name=?,code=?,description=? WHERE id=?');$s->execute([$title,$grade,$field,$code,$description,$id]);audit('edit_subject','subjects',$id);flash('success','درس ویرایش شد.');}else{$s=db()->prepare('INSERT INTO subjects(title,grade_level,field_name,code,description,created_by) VALUES(?,?,?,?,?,?)');$s->execute([$title,$grade,$field,$code,$description,$uid]);$newId=(int)db()->lastInsertId();audit('add_subject','subjects',$newId);flash('success','درس جدید اضافه شد.');}redirect('admin/subjects.php');}
 }
 if($action==='toggle'&&$id){$s=db()->prepare('UPDATE subjects SET is_active=1-is_active WHERE id=?');$s->execute([$id]);audit('toggle_subject','subjects',$id);flash('success','وضعیت درس تغییر کرد.');redirect('admin/subjects.php');}
 if($action==='delete'&&$id){$used=db()->prepare('SELECT (SELECT COUNT(*) FROM exams WHERE subject_id=?) + (SELECT COUNT(*) FROM class_subjects WHERE subject_id=?) + (SELECT COUNT(*) FROM question_bank WHERE subject_id=?)');$used->execute([$id,$id,$id]);if((int)$used->fetchColumn()>0){$s=db()->prepare('UPDATE subjects SET is_active=0 WHERE id=?');$s->execute([$id]);flash('warning','این درس در آزمون، کلاس یا بانک سؤال استفاده شده است؛ به‌جای حذف، غیرفعال شد.');}else{$s=db()->prepare('DELETE FROM subjects WHERE id=?');$s->execute([$id]);audit('delete_subject','subjects',$id);flash('success','درس حذف شد.');}redirect('admin/subjects.php');}
}
$editing=null;if($editId){$s=db()->prepare('SELECT * FROM subjects WHERE id=?');$s->execute([$editId]);$editing=$s->fetch();}
$subjects=db()->query('SELECT s.*,u.full_name AS creator_name,(SELECT COUNT(*) FROM question_bank q WHERE q.subject_id=s.id) AS question_count,(SELECT COUNT(*) FROM exams e WHERE e.subject_id=s.id) AS exam_count FROM subjects s LEFT JOIN users u ON u.id=s.created_by ORDER BY s.is_active DESC,s.title')->fetchAll();
$title='مدیریت درس‌ها';require __DIR__.'/../partials/header.php';
?><div class="card class-toolbar"><div><span class="eyebrow">مدیریت محتوای آموزشی</span><h1>مدیریت درس‌ها</h1><p class="muted">مدیر می‌تواند درس‌ها را تعریف، ویرایش، فعال یا غیرفعال کند.</p></div><a class="btn btn-light" href="<?=e(url('admin/index.php'))?>">بازگشت به داشبورد</a></div><?php if($errors):?><div class="alert danger"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><div class="grid grid-2"><div class="card"><h2><?=$editing?'ویرایش درس':'افزودن درس جدید'?></h2><form method="post" class="grid"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$editing['id']??0?>"><div class="form-group"><label>عنوان درس</label><input name="title" maxlength="150" required value="<?=e($editing['title']??'')?>" placeholder="مثلاً: الزامات محیط کار"></div><div class="form-group"><label>پایه</label><select name="grade_level"><option value="">انتخاب پایه</option><?php foreach(['دهم','یازدهم','دوازدهم'] as $grade):?><option value="<?=e($grade)?>" <?=($editing&&($editing['grade_level']??'')===$grade)?'selected':''?>><?=e($grade)?></option><?php endforeach;?></select></div><div class="form-group"><label>رشته</label><input name="field_name" maxlength="150" value="<?=e($editing['field_name']??'')?>" placeholder="مثلاً: شبکه و نرم‌افزار"></div><div class="form-group"><label>کد درس</label><input name="code" maxlength="50" value="<?=e($editing['code']??'')?>" placeholder="اختیاری"></div><div class="form-group"><label>توضیحات</label><textarea name="description" rows="4"><?=e($editing['description']??'')?></textarea></div><button class="btn btn-success">ذخیره درس</button><?php if($editing):?><a class="btn btn-light" href="<?=e(url('admin/subjects.php'))?>">لغو ویرایش</a><?php endif;?></form></div><div class="card"><h2>راهنمای مدیریت درس</h2><p class="muted">پس از ایجاد درس، آن را در کلاس‌ها و بانک سؤال استفاده کنید. غیرفعال‌کردن درس، سؤال‌ها و آزمون‌های قبلی را حذف نمی‌کند و فقط استفادهٔ جدید از آن را محدود می‌سازد.</p><div class="stat-grid"><div class="stat-card"><strong><?=count($subjects)?></strong><span>کل درس‌ها</span></div><div class="stat-card"><strong><?=count(array_filter($subjects,fn($s)=>(int)$s['is_active']===1))?></strong><span>درس فعال</span></div></div></div></div><div class="card table-wrap"><h2>فهرست درس‌ها</h2><table class="table"><thead><tr><th>شماره</th><th>عنوان</th><th>پایه</th><th>رشته</th><th>کد</th><th>سازنده</th><th>سؤال‌ها</th><th>آزمون‌ها</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($subjects as $i=>$s):?><tr><td><?=e((string)($i+1))?></td><td><strong><?=e($s['title'])?></strong><br><small><?=e($s['description']??'')?></small></td><td><?=e($s['grade_level']??'—')?></td><td><?=e($s['field_name']??'همه رشته‌ها')?></td><td><?=e($s['code']??'—')?></td><td><?=e($s['creator_name']??'مدیر')?></td><td><?=e((string)$s['question_count'])?></td><td><?=e((string)$s['exam_count'])?></td><td><?=((int)$s['is_active']===1)?'فعال':'غیرفعال'?></td><td><div class="actions"><a class="btn btn-sm btn-light" href="<?=e(url('admin/subjects.php?edit='.$s['id']))?>">ویرایش</a><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn btn-sm btn-light">فعال/غیرفعال</button></form><form method="post" style="display:inline" onsubmit="return confirm('درس حذف یا غیرفعال شود؟')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn btn-sm btn-danger">حذف</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
